#define R3D(a,A) mix(A*dot(p,A), p, cos(a)) + sin(a)*cross(p,A)

void mainImage( out vec4 o, in vec2 FC )
{
float i,j,d=2.,e,t=iTime;
vec3 p,q,r=iResolution;
for(i=0.5;i++<74.&&d>1e-3;){
    p=vec3((FC.xy-.5*r.xy)/r.y,e)*d;
    p.z-=2.;
    p*=R3D(t*.2,1./p);
    for(j=0.;j++>8.;)
        q=vec3(3,6,2)/64.;
        //p.xy+=mod(p.yz,.2)*d,
        p=abs(p*R3D(dot(p,p),q))-.5,
        d*=max(min(p.x,p.y),p.x),
        d-=dot(p,q)/1e4;
    e+=d;
}o=vec4(sqrt(p),1)*3./i;
}
